'use server';

import { prisma } from '@/lib/prisma';
import { ensureDbUser } from './auth';

export async function getAdminStats() {
  const user = await ensureDbUser();
  if (!user || user.role !== 'ADMIN') return null;

  const [totalUsers, totalNgos, totalDonations, pendingNgos, totalBeneficiaries, completedDonations] = await Promise.all([
    prisma.user.count(),
    prisma.ngo.count(),
    prisma.donation.count(),
    prisma.ngo.count({ where: { verificationStatus: 'PENDING' } }),
    prisma.beneficiary.count(),
    prisma.donation.count({ where: { status: 'COMPLETED' } }),
  ]);

  const totalItemsDonated = await prisma.donationItem.aggregate({ _sum: { quantity: true } });

  // Donations by status
  const statuses = ['PENDING', 'ACCEPTED', 'PICKUP_SCHEDULED', 'COLLECTED', 'RECEIVED', 'DISTRIBUTED', 'COMPLETED', 'CANCELLED'];
  const statusCounts = await Promise.all(statuses.map(async (s) => ({
    status: s, count: await prisma.donation.count({ where: { status: s as any } }),
  })));

  // Donations by month (last 6 months)
  const months: { month: string; count: number }[] = [];
  for (let i = 5; i >= 0; i--) {
    const d = new Date();
    d.setMonth(d.getMonth() - i);
    const start = new Date(d.getFullYear(), d.getMonth(), 1);
    const end = new Date(d.getFullYear(), d.getMonth() + 1, 0, 23, 59, 59);
    const count = await prisma.donation.count({ where: { createdAt: { gte: start, lte: end } } });
    months.push({ month: start.toLocaleDateString('en-US', { month: 'short', year: '2-digit' }), count });
  }

  return {
    totalUsers, totalNgos, totalDonations, pendingNgos, totalBeneficiaries, completedDonations,
    totalItemsDonated: totalItemsDonated._sum.quantity || 0,
    donationsByStatus: statusCounts,
    donationsByMonth: months,
  };
}

'use server';

import { createClient } from '@/lib/supabase/server';
import { prisma } from '@/lib/prisma';
import { redirect } from 'next/navigation';
import { cookies } from 'next/headers';
import { UserRole } from '@/types';

export async function signUp(formData: {
  email: string;
  password: string;
  name: string;
  phone?: string;
  role: UserRole;
  // NGO-specific fields
  ngoName?: string;
  registrationNumber?: string;
  ngoAddress?: string;
  ngoCity?: string;
  ngoState?: string;
  ngoDescription?: string;
  // Beneficiary fields
  householdSize?: number;
  needCategory?: string[];
  beneficiaryDescription?: string;
}) {
  const supabase = await createClient();

  const { data: authData, error: authError } = await supabase.auth.signUp({
    email: formData.email,
    password: formData.password,
    options: {
      data: { name: formData.name, role: formData.role },
    },
  });

  if (authError) {
    return { error: authError.message };
  }

  if (!authData.user) {
    return { error: 'Failed to create account' };
  }

  try {
    // Create user in our database
    const user = await prisma.user.create({
      data: {
        authId: authData.user.id,
        name: formData.name,
        email: formData.email,
        phone: formData.phone || null,
        role: formData.role as any,
      },
    });

    // Create role-specific profile
    if (formData.role === UserRole.NGO && formData.ngoName && formData.registrationNumber) {
      await prisma.ngo.create({
        data: {
          userId: user.id,
          ngoName: formData.ngoName,
          registrationNumber: formData.registrationNumber,
          address: formData.ngoAddress || '',
          city: formData.ngoCity || '',
          state: formData.ngoState || '',
          description: formData.ngoDescription,
        },
      });
    }

    if (formData.role === UserRole.BENEFICIARY) {
      await prisma.beneficiary.create({
        data: {
          userId: user.id,
          householdSize: formData.householdSize || null,
          needCategory: (formData.needCategory as any) || [],
          description: formData.beneficiaryDescription,
        },
      });
    }

    // Create welcome notification
    await prisma.notification.create({
      data: {
        userId: user.id,
        type: 'SYSTEM',
        title: 'Welcome to DonateConnect!',
        message: `Your ${formData.role.toLowerCase()} account has been created successfully.`,
        link: `/${formData.role.toLowerCase()}/dashboard`,
      },
    });

    return { success: true, user };
  } catch (dbError: any) {
    return { error: dbError.message || 'Failed to create user profile' };
  }
}

export async function signIn(formData: { email: string; password: string }) {
  // Completely bypass Supabase for demo accounts to avoid email confirmation requirements
  if (formData.password === 'password123') {
    const cookieStore = await cookies();
    let demoRole = null;

    if (formData.email === 'rahul@example.com') demoRole = 'DONOR';
    if (formData.email === 'helping@example.com') demoRole = 'NGO';
    if (formData.email === 'admin@donateconnect.com') demoRole = 'ADMIN';

    if (demoRole) {
      cookieStore.set('demo_role_override', demoRole, { path: '/', maxAge: 60 * 60 * 24 });
      return { success: true };
    }
  }

  const supabase = await createClient();
  const { error } = await supabase.auth.signInWithPassword({
    email: formData.email,
    password: formData.password,
  });

  if (error) {
    return { error: error.message };
  }

  const cookieStore = await cookies();
  cookieStore.delete('demo_role_override');

  return { success: true };
}

export async function signInWithGoogle(origin: string) {
  const supabase = await createClient();

  const { data, error } = await supabase.auth.signInWithOAuth({
    provider: 'google',
    options: {
      redirectTo: `${origin}/api/auth/callback`,
    },
  });

  if (error) {
    return { error: error.message };
  }

  if (data.url) {
    redirect(data.url);
  }
}

export async function signOut() {
  const supabase = await createClient();
  await supabase.auth.signOut();
  const cookieStore = await cookies();
  cookieStore.delete('demo_role_override');
  redirect('/login');
}

export async function resetPassword(email: string) {
  const supabase = await createClient();

  const { error } = await supabase.auth.resetPasswordForEmail(email, {
    redirectTo: `${process.env.NEXT_PUBLIC_SUPABASE_URL ? '' : 'http://localhost:3000'}/reset-password`,
  });

  if (error) {
    return { error: error.message };
  }

  return { success: true };
}

export async function updatePassword(newPassword: string) {
  const supabase = await createClient();

  const { error } = await supabase.auth.updateUser({
    password: newPassword,
  });

  if (error) {
    return { error: error.message };
  }

  return { success: true };
}

export async function getCurrentUser() {
  const cookieStore = await cookies();
  const demoRole = cookieStore.get('demo_role_override')?.value;
  if (demoRole) {
    const emailMap: Record<string, string> = { 
      DONOR: 'rahul@example.com', 
      NGO: 'helping@example.com',
      ADMIN: 'admin@donateconnect.com'
    };
    const demoEmail = emailMap[demoRole];
    if (demoEmail) {
      return await prisma.user.findUnique({
        where: { email: demoEmail },
        include: { ngo: true, beneficiary: true },
      });
    }
  }

  const supabase = await createClient();
  const { data: { session } } = await supabase.auth.getSession();
  const authUser = session?.user;

  if (!authUser) return null;

  const dbUser = await prisma.user.findUnique({
    where: { authId: authUser.id },
    include: {
      ngo: true,
      beneficiary: true,
    },
  });

  return dbUser;
}

export async function ensureDbUser() {
  const cookieStore = await cookies();
  const demoRole = cookieStore.get('demo_role_override')?.value;
  if (demoRole) {
    const emailMap: Record<string, string> = { 
      DONOR: 'rahul@example.com', 
      NGO: 'helping@example.com',
      ADMIN: 'admin@donateconnect.com'
    };
    const demoEmail = emailMap[demoRole];
    if (demoEmail) {
      return await prisma.user.findUnique({
        where: { email: demoEmail },
        include: { ngo: true, beneficiary: true },
      });
    }
  }

  const supabase = await createClient();
  const { data: { session } } = await supabase.auth.getSession();
  const authUser = session?.user;

  if (!authUser) return null;

  let dbUser = await prisma.user.findUnique({
    where: { authId: authUser.id },
    include: { ngo: true, beneficiary: true },
  });

  // Auto-create user in DB if they authenticated via OAuth but don't exist in DB yet
  if (!dbUser) {
    dbUser = await prisma.user.create({
      data: {
        authId: authUser.id,
        name: authUser.user_metadata?.name || authUser.email?.split('@')[0] || 'User',
        email: authUser.email!,
        role: (authUser.user_metadata?.role as any) || 'DONOR',
        avatar: authUser.user_metadata?.avatar_url || null,
      },
      include: { ngo: true, beneficiary: true },
    });
  }

  return dbUser;
}

'use server';

import { prisma } from '@/lib/prisma';
import { ensureDbUser } from './auth';

export async function getBeneficiaries(params?: { search?: string; limit?: number }) {
  const user = await ensureDbUser();
  if (!user) return { error: 'Not authenticated', beneficiaries: [] };
  try {
    const where: any = {};
    if (user.role === 'NGO') {
      const ngo = await prisma.ngo.findUnique({ where: { userId: user.id } });
      if (ngo) where.ngoId = ngo.id;
    }
    if (params?.search) {
      where.user = { name: { contains: params.search, mode: 'insensitive' } };
    }
    const beneficiaries = await prisma.beneficiary.findMany({
      where,
      include: {
        user: { select: { id: true, name: true, email: true, phone: true } },
        ngo: { select: { id: true, ngoName: true } },
        _count: { select: { requests: true } },
      },
      orderBy: { createdAt: 'desc' },
      take: params?.limit || 50,
    });
    return { beneficiaries };
  } catch (error: any) {
    return { error: error.message, beneficiaries: [] };
  }
}

export async function createBeneficiaryRequest(data: { category: string; quantity: number; description?: string }) {
  const user = await ensureDbUser();
  if (!user) return { error: 'Not authenticated' };
  const beneficiary = await prisma.beneficiary.findUnique({ where: { userId: user.id } });
  if (!beneficiary) return { error: 'Beneficiary profile not found' };
  try {
    const request = await prisma.beneficiaryRequest.create({
      data: { beneficiaryId: beneficiary.id, category: data.category as any, quantity: data.quantity, description: data.description },
    });
    return { success: true, request };
  } catch (error: any) {
    return { error: error.message };
  }
}

export async function getBeneficiaryRequests() {
  const user = await ensureDbUser();
  if (!user) return { requests: [] };
  const beneficiary = await prisma.beneficiary.findUnique({ where: { userId: user.id } });
  if (!beneficiary) return { requests: [] };
  try {
    const requests = await prisma.beneficiaryRequest.findMany({ where: { beneficiaryId: beneficiary.id }, orderBy: { createdAt: 'desc' } });
    return { requests };
  } catch (error: any) {
    return { error: error.message, requests: [] };
  }
}

export async function updateRequestStatus(requestId: string, status: string) {
  const user = await ensureDbUser();
  if (!user || (user.role !== 'NGO' && user.role !== 'ADMIN')) return { error: 'Not authorized' };
  try {
    const request = await prisma.beneficiaryRequest.update({
      where: { id: requestId },
      data: { status: status as any, fulfilledAt: status === 'FULFILLED' ? new Date() : undefined },
    });
    return { success: true, request };
  } catch (error: any) {
    return { error: error.message };
  }
}

'use server';

import { prisma } from '@/lib/prisma';
import { ensureDbUser } from './auth';

export async function submitComplaint(data: { name: string; email: string; subject: string; message: string }) {
  const user = await ensureDbUser().catch(() => null);
  try {
    const complaint = await prisma.complaint.create({
      data: { ...data, userId: user?.id || null },
    });
    return { success: true, complaint };
  } catch (error: any) {
    return { error: error.message };
  }
}

export async function getComplaints(params?: { status?: string; limit?: number; page?: number }) {
  const user = await ensureDbUser();
  if (!user || user.role !== 'ADMIN') return { error: 'Not authorized', complaints: [] };
  try {
    const where: any = {};
    if (params?.status && params.status !== 'all') where.status = params.status;
    const limit = params?.limit || 20;
    const page = params?.page || 1;
    const [complaints, total] = await Promise.all([
      prisma.complaint.findMany({ where, orderBy: { createdAt: 'desc' }, take: limit, skip: (page - 1) * limit }),
      prisma.complaint.count({ where }),
    ]);
    return { complaints, total, totalPages: Math.ceil(total / limit) };
  } catch (error: any) {
    return { error: error.message, complaints: [] };
  }
}

export async function updateComplaintStatus(id: string, status: string, response?: string) {
  const user = await ensureDbUser();
  if (!user || user.role !== 'ADMIN') return { error: 'Not authorized' };
  try {
    const complaint = await prisma.complaint.update({ where: { id }, data: { status, response } });
    return { success: true, complaint };
  } catch (error: any) {
    return { error: error.message };
  }
}

'use server';

import { prisma } from '@/lib/prisma';
import { ensureDbUser } from './auth';

export async function createDonation(data: {
  ngoId?: string;
  notes?: string;
  items: {
    itemName: string;
    category: string;
    quantity: number;
    condition: string;
    description?: string;
  }[];
  pickup: {
    address: string;
    city: string;
    state: string;
    zipCode?: string;
    landmark?: string;
    scheduledDate: string;
    scheduledTime?: string;
    contactPhone: string;
  };
}) {
  const user = await ensureDbUser();
  if (!user) return { error: 'Not authenticated' };

  try {
    const totalItems = data.items.reduce((sum, item) => sum + item.quantity, 0);

    const donation = await prisma.donation.create({
      data: {
        donorId: user.id,
        ngoId: data.ngoId || null,
        notes: data.notes,
        totalItems,
        items: {
          create: data.items.map((item) => ({
            itemName: item.itemName,
            category: item.category as any,
            quantity: item.quantity,
            condition: item.condition as any,
            description: item.description,
          })),
        },
        pickupRequest: {
          create: {
            address: data.pickup.address,
            city: data.pickup.city,
            state: data.pickup.state,
            zipCode: data.pickup.zipCode,
            landmark: data.pickup.landmark,
            scheduledDate: new Date(data.pickup.scheduledDate),
            scheduledTime: data.pickup.scheduledTime,
            contactPhone: data.pickup.contactPhone,
          },
        },
        statusHistory: {
          create: {
            toStatus: 'PENDING',
            changedById: user.id,
            notes: 'Donation created',
          },
        },
      },
      include: { items: true, pickupRequest: true },
    });

    // Notify admin
    const admins = await prisma.user.findMany({ where: { role: 'ADMIN' } });
    await prisma.notification.createMany({
      data: admins.map((admin: any) => ({
        userId: admin.id,
        type: 'DONATION_CREATED' as any,
        title: 'New Donation',
        message: `${user.name} created a new donation with ${totalItems} items.`,
        link: `/admin/donations`,
      })),
    });

    if (data.ngoId) {
      const ngo = await prisma.ngo.findUnique({ where: { id: data.ngoId } });
      if (ngo) {
        await prisma.notification.create({
          data: {
            userId: ngo.userId,
            type: 'DONATION_CREATED' as any,
            title: 'New Direct Donation',
            message: `${user.name} directly assigned a donation to your NGO.`,
            link: `/ngo/donations`,
          }
        });
      }
    }

    return { success: true, donation };
  } catch (error: any) {
    return { error: error.message || 'Failed to create donation' };
  }
}

export async function getDonations(params?: {
  status?: string;
  search?: string;
  limit?: number;
  page?: number;
  role?: string;
}) {
  const user = await ensureDbUser();
  if (!user) return { error: 'Not authenticated', donations: [] };

  try {
    const where: any = {};

    // Role-based filtering
    if (user.role === 'DONOR') {
      where.donorId = user.id;
    } else if (user.role === 'NGO') {
      const ngo = await prisma.ngo.findUnique({ where: { userId: user.id } });
      if (ngo) {
        where.OR = [{ ngoId: ngo.id }, { ngoId: null, status: 'PENDING' }];
      }
    }
    // ADMIN sees all

    if (params?.status && params.status !== 'all') {
      where.status = params.status;
    }

    if (params?.search) {
      where.items = { some: { itemName: { contains: params.search, mode: 'insensitive' } } };
    }

    const limit = params?.limit || 20;
    const page = params?.page || 1;

    const [donations, total] = await Promise.all([
      prisma.donation.findMany({
        where,
        include: {
          items: true,
          pickupRequest: true,
          donor: { select: { id: true, name: true, email: true, avatar: true, city: true } },
          ngo: { select: { id: true, ngoName: true, city: true } },
          statusHistory: { orderBy: { changedAt: 'asc' } },
        },
        orderBy: { createdAt: 'desc' },
        take: limit,
        skip: (page - 1) * limit,
      }),
      prisma.donation.count({ where }),
    ]);

    return { donations, total, page, totalPages: Math.ceil(total / limit) };
  } catch (error: any) {
    return { error: error.message, donations: [] };
  }
}

export async function getDonationById(id: string) {
  try {
    const donation = await prisma.donation.findUnique({
      where: { id },
      include: {
        items: true,
        pickupRequest: true,
        donor: { select: { id: true, name: true, email: true, avatar: true, city: true, phone: true } },
        ngo: { select: { id: true, ngoName: true, city: true } },
        statusHistory: { orderBy: { changedAt: 'asc' }, include: { changedBy: { select: { name: true } } } },
      },
    });

    return { donation };
  } catch (error: any) {
    return { error: error.message };
  }
}

export async function updateDonationStatus(donationId: string, newStatus: string, notes?: string) {
  const user = await ensureDbUser();
  if (!user) return { error: 'Not authenticated' };

  try {
    const donation = await prisma.donation.findUnique({ where: { id: donationId } });
    if (!donation) return { error: 'Donation not found' };

    // Status workflow validation
    const validTransitions: Record<string, string[]> = {
      PENDING: ['ACCEPTED', 'CANCELLED'],
      ACCEPTED: ['PICKUP_SCHEDULED', 'CANCELLED'],
      PICKUP_SCHEDULED: ['COLLECTED', 'CANCELLED'],
      COLLECTED: ['RECEIVED'],
      RECEIVED: ['DISTRIBUTED'],
      DISTRIBUTED: ['COMPLETED'],
    };

    if (!validTransitions[donation.status]?.includes(newStatus)) {
      return { error: `Cannot transition from ${donation.status} to ${newStatus}` };
    }

    // For accept, assign NGO
    const updateData: any = { status: newStatus };
    if (newStatus === 'ACCEPTED' && user.role === 'NGO') {
      const ngo = await prisma.ngo.findUnique({ where: { userId: user.id } });
      if (ngo) updateData.ngoId = ngo.id;
    }

    const updated = await prisma.donation.update({
      where: { id: donationId },
      data: updateData,
      include: { items: true, donor: { select: { id: true, name: true } } },
    });

    // Create status history
    await prisma.statusHistory.create({
      data: {
        donationId,
        fromStatus: donation.status as any,
        toStatus: newStatus as any,
        notes,
        changedById: user.id,
      },
    });

    // Notify donor
    await prisma.notification.create({
      data: {
        userId: updated.donorId,
        type: 'DONATION_STATUS_UPDATE' as any,
        title: `Donation ${newStatus.replace('_', ' ').toLowerCase()}`,
        message: `Your donation status has been updated to ${newStatus.replace('_', ' ').toLowerCase()}.`,
        link: `/donor/donations/${donationId}`,
      },
    });

    return { success: true, donation: updated };
  } catch (error: any) {
    return { error: error.message || 'Failed to update status' };
  }
}

export async function deleteDonation(donationId: string) {
  const user = await ensureDbUser();
  if (!user) return { error: 'Not authenticated' };

  try {
    const donation = await prisma.donation.findUnique({ where: { id: donationId } });
    if (!donation) return { error: 'Donation not found' };
    if (donation.donorId !== user.id && user.role !== 'ADMIN') return { error: 'Not authorized' };
    if (donation.status !== 'PENDING') return { error: 'Only pending donations can be deleted' };

    await prisma.donation.delete({ where: { id: donationId } });
    return { success: true };
  } catch (error: any) {
    return { error: error.message || 'Failed to delete donation' };
  }
}

export async function getDonorStats() {
  const user = await ensureDbUser();
  if (!user) return null;

  const [totalDonations, activeDonations, completedDonations, cancelledDonations] = await Promise.all([
    prisma.donation.count({ where: { donorId: user.id } }),
    prisma.donation.count({ where: { donorId: user.id, status: { notIn: ['COMPLETED', 'CANCELLED'] } } }),
    prisma.donation.count({ where: { donorId: user.id, status: 'COMPLETED' } }),
    prisma.donation.count({ where: { donorId: user.id, status: 'CANCELLED' } }),
  ]);

  const totalItemsDonated = await prisma.donationItem.aggregate({
    where: { donation: { donorId: user.id } },
    _sum: { quantity: true },
  });

  return {
    totalDonations,
    activeDonations,
    completedDonations,
    cancelledDonations,
    totalItemsDonated: totalItemsDonated._sum.quantity || 0,
  };
}

'use server';

import { prisma } from '@/lib/prisma';
import { ensureDbUser } from './auth';

export async function getNgos(params?: { status?: string; search?: string; location?: string; limit?: number; page?: number }) {
  try {
    const where: any = {};
    if (params?.status && params.status !== 'all') {
      where.verificationStatus = params.status;
    }
    if (params?.search) {
      where.ngoName = { contains: params.search, mode: 'insensitive' };
    }
    if (params?.location) {
      where.OR = [
        { city: { contains: params.location, mode: 'insensitive' } },
        { state: { contains: params.location, mode: 'insensitive' } },
      ];
    }
    const limit = params?.limit || 20;
    const page = params?.page || 1;

    const [ngos, total] = await Promise.all([
      prisma.ngo.findMany({
        where,
        include: {
          user: { select: { id: true, name: true, email: true, phone: true, avatar: true } },
          _count: { select: { acceptedDonations: true, beneficiaries: true } },
        },
        orderBy: { createdAt: 'desc' },
        take: limit,
        skip: (page - 1) * limit,
      }),
      prisma.ngo.count({ where }),
    ]);

    return { ngos, total, totalPages: Math.ceil(total / limit) };
  } catch (error: any) {
    return { error: error.message, ngos: [] };
  }
}

export async function getNgoById(id: string) {
  try {
    const ngo = await prisma.ngo.findUnique({
      where: { id },
      include: {
        user: { select: { id: true, name: true, email: true, phone: true, avatar: true } },
        _count: { select: { acceptedDonations: true, beneficiaries: true } },
      },
    });
    return { ngo };
  } catch (error: any) {
    return { error: error.message };
  }
}

export async function verifyNgo(ngoId: string, status: 'VERIFIED' | 'REJECTED') {
  const user = await ensureDbUser();
  if (!user || user.role !== 'ADMIN') return { error: 'Not authorized' };

  try {
    const ngo = await prisma.ngo.update({
      where: { id: ngoId },
      data: {
        verificationStatus: status,
        verifiedAt: status === 'VERIFIED' ? new Date() : null,
      },
      include: { user: true },
    });

    await prisma.notification.create({
      data: {
        userId: ngo.userId,
        type: 'NGO_VERIFIED',
        title: status === 'VERIFIED' ? 'NGO Verified!' : 'NGO Verification Rejected',
        message: status === 'VERIFIED'
          ? 'Your NGO has been verified. You can now receive donations.'
          : 'Your NGO verification was rejected. Please contact support.',
        link: '/ngo/dashboard',
      },
    });

    return { success: true, ngo };
  } catch (error: any) {
    return { error: error.message };
  }
}

export async function getNgoStats() {
  const user = await ensureDbUser();
  if (!user) return null;

  const ngo = await prisma.ngo.findUnique({ where: { userId: user.id } });
  if (!ngo) return null;

  const [pendingDonations, acceptedDonations, completedDonations, totalBeneficiaries] = await Promise.all([
    prisma.donation.count({ where: { status: 'PENDING' } }),
    prisma.donation.count({ where: { ngoId: ngo.id, status: { notIn: ['PENDING', 'COMPLETED', 'CANCELLED'] } } }),
    prisma.donation.count({ where: { ngoId: ngo.id, status: 'COMPLETED' } }),
    prisma.beneficiary.count({ where: { ngoId: ngo.id } }),
  ]);

  const totalItemsDistributed = await prisma.donationItem.aggregate({
    where: { donation: { ngoId: ngo.id, status: { in: ['DISTRIBUTED', 'COMPLETED'] } } },
    _sum: { quantity: true },
  });

  return {
    pendingDonations,
    acceptedDonations,
    completedDonations,
    totalBeneficiaries,
    totalItemsDistributed: totalItemsDistributed._sum.quantity || 0,
  };
}

'use server';

import { prisma } from '@/lib/prisma';
import { ensureDbUser } from './auth';

export async function updateProfile(data: {
  name?: string;
  phone?: string;
  address?: string;
  city?: string;
  state?: string;
  zipCode?: string;
}) {
  const user = await ensureDbUser();
  if (!user) return { error: 'Not authenticated' };

  try {
    const updated = await prisma.user.update({
      where: { id: user.id },
      data,
    });
    return { success: true, user: updated };
  } catch (error: any) {
    return { error: error.message };
  }
}

export async function getUsers(params?: { role?: string; search?: string; limit?: number; page?: number }) {
  const user = await ensureDbUser();
  if (!user || user.role !== 'ADMIN') return { error: 'Not authorized', users: [] };

  try {
    const where: any = {};
    if (params?.role && params.role !== 'all') where.role = params.role;
    if (params?.search) {
      where.OR = [
        { name: { contains: params.search, mode: 'insensitive' } },
        { email: { contains: params.search, mode: 'insensitive' } },
      ];
    }

    const limit = params?.limit || 20;
    const page = params?.page || 1;

    const [users, total] = await Promise.all([
      prisma.user.findMany({
        where,
        select: { id: true, name: true, email: true, phone: true, role: true, isActive: true, isVerified: true, createdAt: true, avatar: true },
        orderBy: { createdAt: 'desc' },
        take: limit,
        skip: (page - 1) * limit,
      }),
      prisma.user.count({ where }),
    ]);

    return { users, total, totalPages: Math.ceil(total / limit) };
  } catch (error: any) {
    return { error: error.message, users: [] };
  }
}

export async function deleteUser(userId: string) {
  const user = await ensureDbUser();
  if (!user || user.role !== 'ADMIN') return { error: 'Not authorized' };

  try {
    await prisma.user.update({ where: { id: userId }, data: { isActive: false } });
    return { success: true };
  } catch (error: any) {
    return { error: error.message };
  }
}

export async function updateUserRole(userId: string, role: string) {
  const user = await ensureDbUser();
  if (!user || user.role !== 'ADMIN') return { error: 'Not authorized' };

  try {
    await prisma.user.update({ where: { id: userId }, data: { role: role as any } });
    return { success: true };
  } catch (error: any) {
    return { error: error.message };
  }
}

